def add_release_effects(ev):
    """Gate every sustained (looped) note: fade out in the 2 rows before the next note
    on the same channel (A0F = volume slide down 15/tick). Wraps the loop seam:
    the last notes of the song release before the restart note at bar RESTART_BAR."""
    for ch in (CH_LEAD, CH_HARM, CH_BASS, CH_PAD1, CH_PAD2):
        rows = sorted(ev[ch].keys())
        loop_rows = [r for r in rows if r >= RESTART_ROW]
        for i, r in enumerate(rows):
            if i + 1 < len(rows):
                nxt = rows[i + 1]
            elif loop_rows:
                nxt = loop_rows[0] + SONG_ROWS - RESTART_ROW
            else:
                continue
            for rr in (nxt - 2, nxt - 1):
                if r <= rr < nxt:
                    row = rr % SONG_ROWS
                    if row in ev[ch] and ev[ch][row].get('fx') not in (None, 10):
                        continue
                    cell = ev[ch].get(row, {})
                    cell['fx'] = 10; cell['fxp'] = 0x0F
                    ev[ch][row] = cell
    return ev


def pattern_cells(ev, b):
    base = (b - 1) * ROWS_PER_BAR
    cells = []
    for ch in range(NCH):
        for r in range(ROWS_PER_BAR):
            c = ev[ch].get(base + r)
            if c:
                cells.append(dict(row=r, channel=ch, **c))
    return cells


def main():
    ev = add_release_effects(build_events())
    # dedupe bars into patterns
    pats, bar_pat = [], {}
    key_to = {}
