"""Isolated instrument probe: one note in a 1-pattern song (run inside the FT2 session)."""
import json, subprocess, wave, numpy as np, sys
def ft(name, args):
    return subprocess.run(['ft2','call',name,json.dumps(args)],capture_output=True,text=True)
def cell(note, ins, ch=0, vol=None, fx=None, fxp=None, row=0):
    a={"pattern":0,"row":row,"channel":ch,"note":note,"instrument":ins}
    if vol is not None: a["volume"]=vol
    if fx is not None: a["effect"]=fx; a["effect_param"]=fxp
    return a
def setup_single(cells, rows=32):
    calls=[{"name":"song_set","arguments":{"length":1,"loop_start":0}},
           {"name":"order_set","arguments":{"position":0,"pattern":0}},
           {"name":"pattern_clear","arguments":{"pattern":0}},
           {"name":"pattern_set_length","arguments":{"pattern":0,"rows":rows}}]
    calls+=[{"name":"pattern_set_cell","arguments":c} for c in cells]
    json.dump(calls,open('/workspace/build/t.json','w'))
    subprocess.run(['ft2','batch','/workspace/build/t.json'],capture_output=True)
def render_stats(path="/workspace/build/t_iso.wav", secs=(0.02,0.40)):
    ft('module_render',{"path":path,"rate":44100,"bits":16,"loops":1})
    w=wave.open(path,'rb'); c=w.getnchannels(); x=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float).reshape(-1,c)/32768
    m=x.mean(axis=1)
    s0,s1=int(secs[0]*44100),int(secs[1]*44100)
    return dict(peak=round(float(np.abs(x).max()),3), rms=round(float(np.sqrt((m[s0:s1]**2).mean())),4), n=len(m))
if __name__=="__main__":
    tests=[("Kick C4",1,49),("Snare C4",2,49),("HatC C4",3,49),("HatO C4",4,49),
