import sys, json, numpy as np
sys.path.insert(0,'/workspace/build')
import synth, compose
from xmcheck import read_xm
m = read_xm('/workspace/submission/tune.xm')
print("header:", {k:m[k] for k in ('name','tracker','version','song_len','restart','nch','npat','nins','speed','bpm')})
bad=0
for idx,name,builder,rel,vol,pan,loop in synth.INSTRUMENTS:
    ins=m['instruments'][idx-1]
    want=synth.to_int16(builder()).astype(np.int32)
    s=ins['samples'][0]
    got=s['data'].astype(np.int32)
    ok = len(want)==len(got) and np.array_equal(want,got) and set(ins['keymap_set'])=={0}
    ok = ok and s['volume']==vol and s['pan']==pan and s['relnote']==rel and s['finetune']==0
    ok = ok and ((s['type']&3)==(1 if loop else 0)) and ((s['type']&16)!=0) and ((s['loop_len']//2)==(len(want) if loop else 0))
    if not ok: bad+=1; print("instrument mismatch", idx, name)
print("instruments verified:", len(m['instruments'])-bad, "/", len(m['instruments']))
ev = compose.add_release_effects(compose.build_events())
pats=[]; key_to={}; bar_pat={}
for b in range(1, compose.NBARS+1):
    cells=compose.pattern_cells(ev,b); key=json.dumps(cells,sort_keys=True)
    if key not in key_to: key_to[key]=len(pats); pats.append(cells)
    bar_pat[b]=key_to[key]
mism=0; checked=0
for p,cells in enumerate(pats):
    grid=m['patterns'][p]['grid']
    expect={}
    for c in cells:
        expect[(c['row'],c['channel'])]=(c.get('note',0), c.get('inst',0), c.get('vol',0), c.get('fx',0), c.get('fxp',0))
    for r in range(32):
        for chn in range(m['nch']):
            got=grid[r][chn]; want=expect.get((r,chn),(0,0,0,0,0)); checked+=1
            if got[0]!=want[0] or got[1]!=want[1] or got[2]!=want[2] or got[3]!=want[3] or (want[3]!=0 and got[4]!=want[4]) or (want[3]==0 and got[4]!=0):
                mism+=1
